tool_calls:
awk '
function trim(s) { sub(/^[[:space:]]+/, "", s); sub(/[[:space:]]+$/, "", s); return s }
{
  line = trim($0)
  if (line == "" || line ~ /^[;#]/) next
  if (line ~ /^\[.*\]$/) {
    sec = line
    sub(/^\[/, "", sec); sub(/\]$/, "", sec)
    if (FILENAME == "/config/defaults.ini") {
      if (!(sec in dsec_seen)) { dsec_seen[sec]=1; dsec[++ndsec]=sec }
    } else {
      if (!(sec in csec_seen)) { csec_seen[sec]=1; csec[++ncsec]=sec }
    }
    next
  }
  eq = index(line, "=")
  if (!eq) next
  key = trim(substr(line, 1, eq-1)); val = trim(substr(line, eq+1))
  id = sec SUBSEP key
  if (FILENAME == "/config/defaults.ini") {
    if (!(id in dkey_seen)) { dkey_seen[id]=1; dkeys[sec, ++dcount[sec]]=key }
    dval[id]=val
  } else {
    if (!(id in ckey_seen)) { ckey_seen[id]=1; ckeys[sec, ++ccount[sec]]=key }
    cval[id]=val
  }
}
END {
  for (i=1; i<=ndsec; i++) {
    s=dsec[i]; print "[" s "]"
    for (j=1; j<=dcount[s]; j++) {
      k=dkeys[s,j]; id=s SUBSEP k
      if (id in cval) print k "=" cval[id]; else print k "=" dval[id]
    }
    for (j=1; j<=ccount[s]; j++) {
      k=ckeys[s,j]; id=s SUBSEP k
      if (!(id in dkey_seen)) print k "=" cval[id]
    }
    print ""
  }
  for (i=1; i<=ncsec; i++) {
    s=csec[i]
    if (s in dsec_seen) continue
    print "[" s "]"
    for (j=1; j<=ccount[s]; j++) { k=ckeys[s,j]; id=s SUBSEP k; print k "=" cval[id] }
    print ""
  }
}' /config/defaults.ini /config/custom.ini > /config/merged.ini
cat /config/merged.ini

